using TabletopTempo.Core.Rhythm;
using UnityEngine;

namespace TabletopTempo.Rhythm
{
    /// <summary>
    /// A .ttchart file imported by the ChartImporter (JSON kept verbatim, parsed on demand).
    /// Charts are generated by tools/music/ttmusic.py; see docs/MUSIC.md.
    /// </summary>
    public sealed class ChartAsset : ScriptableObject
    {
        [TextArea(3, 10)] public string json;

        private Chart _parsed;

        public Chart Chart => _parsed ??= Chart.FromJson(json);

        public static ChartAsset FromJson(string json)
        {
            var a = CreateInstance<ChartAsset>();
            a.json = json;
            return a;
        }
    }

    /// <summary>Everything one stage needs. Created by the project setup for each stage.</summary>
    [CreateAssetMenu(menuName = "Tabletop Tempo/Stage", fileName = "Stage")]
    public sealed class StageDefinition : ScriptableObject
    {
        public int number = 1;
        public string title = "First Claps";
        [TextArea] public string intro = "Clap along with the falling cards.";
        public ChartAsset chart;
        public AudioClip music;

        [Header("Try it (untimed practice)")]
        public MoveId tryMove = MoveId.Clap;
        public int tryReps = 4;
    }
}
